import pandas as pd

def filter_df(df):
    # Check if dataframe and columns exist
    if not isinstance(df, pd.DataFrame) or not set(['Name', 'Hours worked']).issubset(df.columns):
        raise ValueError("The input dataframe must contain 'Name' and 'Hours worked' columns.")
    # Check if data type is integer
    elif not df['Hours worked'].dtype == 'int':
        raise ValueError("The 'Hours worked' column must be of integer type.")
    # Filter rows
    else:
        filtered_df = df[df['Hours worked'] > 40]
        return filtered_df

