def int_to_roman(input):
    """ Convert a floating integer or negative integer to Roman numeral. """
    if not isinstance(input, type(1.0)) and not isinstance(input, type(-1)):
        raise TypeError("Must Enter Either floating Number or Negative Number")
    elif not ((0 < input < 4000) or (input < 0)):
        raise ValueError("Must be >= 0 and < 4000")
    elif input < 0: 
        return '-' + int_to_roman(-input)  # For negative integers, wrap with a "-" sign.
    else: 
        floatorint = int(input)  # Convert the float to int
        ints = (1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1)
        nums = ('M', 'CM', 'D', 'CD', 'C', 'XC', 'L', 'XL', 'X', 'IX', 'V', 'IV', 'I')
        result = []
        for i in range(len(ints)):
            count = floatorint // ints[i]  # use double slashes for floor division in python 3
            result.append(nums[i] * count)
            floatorint -= ints[i] * count
        if str(input) == str(floatorint) + "5":   # to handle floating points like 1.5, 2.5 etc.
            return ''.join(result) + 'V'
        elif str(input) == str(floatorint) + "4": # to handle floating points like 1.4, 2.4 etc.
            return ''.join(result) + 'IV'
        else: 
            return ''.join(result)

